// Edit these, then activate the workflow.
return [{ json: {
  clientLabel: 'Acme Corp (n8n.acme.com)', // shown in every alert
  silentMultiplier: 2,   // SILENT: no success within 2x the expected interval
  failStreak: 3,         // FAILING: this many errors in a row
  slowMultiplier: 3,     // SLOW: last run > 3x median duration
  ignore: [],            // workflow IDs to skip, e.g. ['abc123']
  overrides: {},         // expected interval in minutes for webhook flows, e.g. { def456: 60 }
} }];

// Flow Health Monitor: compute health + dedup (one alert per incident, one on recovery).
// Rules: SILENT = no success within 2x expected interval (and errors don't explain the gap)
//        FAILING = 3+ consecutive errors · SLOW = last duration > 3x median · OK
const cfg = $('Settings').first().json;
const workflows = $('Get Workflows').first().json.data || [];
const executions = $input.first().json.data || [];
const now = Date.now();
const MIN = 60000;
const store = $getWorkflowStaticData('global');
store.incidents = store.incidents || {};

const UNIT = { seconds: 1 / 60, minutes: 1, hours: 60, days: 1440, weeks: 10080, months: 43200 };
const KEY = { seconds: 'secondsInterval', minutes: 'minutesInterval', hours: 'hoursInterval', days: 'daysInterval', weeks: 'weeksInterval', months: 'monthsInterval' };
function cronMin(expr) {
  let f = String(expr || '').trim().split(/\s+/); if (f.length === 6) f = f.slice(1); if (f.length < 5) return null;
  const [mi, h, dom, , dow] = f; const st = (v) => (/^\*\/(\d+)$/.exec(v) || [])[1]; const n = (v) => v.split(',').length;
  if (mi === '*') return 1; if (st(mi)) return +st(mi); if (h === '*') return 60 / n(mi); if (st(h)) return (+st(h) * 60) / n(mi);
  if (dow !== '*' && dom === '*') return 10080 / (n(dow) * n(h) * n(mi)); if (dom !== '*') return 43200 / (n(dom) * n(h) * n(mi));
  return 1440 / (n(h) * n(mi));
}
function intervalOf(wf) {
  if (cfg.overrides && cfg.overrides[wf.id]) return cfg.overrides[wf.id];
  for (const node of wf.nodes || []) {
    if (node.disabled) continue;
    const p = node.parameters || {};
    if (String(node.type).endsWith('.scheduleTrigger')) {
      const rules = (p.rule && p.rule.interval && p.rule.interval.length) ? p.rule.interval : [{ field: 'days' }];
      const mins = rules.map((r) => r.field === 'cronExpression' ? cronMin(r.expression) : (UNIT[r.field || 'days'] || 1440) * (Number(r[KEY[r.field || 'days']] || 1) || 1)).filter(Boolean);
      if (mins.length) return Math.min(...mins);
    }
  }
  return null; // event-driven: inferred below
}
const median = (a) => { a = a.filter(Number.isFinite).sort((x, y) => x - y); if (!a.length) return null; const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };
const fmt = (min) => min < 60 ? `${Math.round(min)} min` : min < 2880 ? `${+(min / 60).toFixed(1)} h` : `${+(min / 1440).toFixed(1)} days`;
const isErr = (s) => ['error', 'crashed', 'failed'].includes(s);

const out = [];
for (const wf of workflows) {
  if ((cfg.ignore || []).includes(String(wf.id)) || String(wf.id) === String($workflow.id)) continue;
  const runs = executions.filter((e) => String(e.workflowId) === String(wf.id))
    .map((e) => ({ status: e.status || (e.finished ? 'success' : 'error'), start: Date.parse(e.startedAt), stop: e.stoppedAt ? Date.parse(e.stoppedAt) : null }))
    .sort((a, b) => b.start - a.start);
  if (wf.active === false && !(runs[0] && now - runs[0].start < 7 * 1440 * MIN)) continue; // skip long-paused flows
  const done = runs.filter((r) => r.status === 'success' || isErr(r.status));
  const oks = done.filter((r) => r.status === 'success');
  let streak = 0; for (const r of done) { if (isErr(r.status)) streak++; else break; }
  let interval = intervalOf(wf);
  if (!interval && runs.length >= 4) {
    const gaps = runs.slice(0, 40).slice(1).map((r, i) => (runs[i].start - r.start) / MIN).sort((a, b) => a - b);
    interval = Math.max(1, Math.round(gaps[Math.round(0.75 * (gaps.length - 1))]));
  }
  const lastOk = oks[0] ? (oks[0].stop || oks[0].start) : null;
  const sinceOk = lastOk ? (now - lastOk) / MIN : null;
  const sinceRun = runs[0] ? (now - (runs[0].stop || runs[0].start)) / MIN : null;
  const limit = interval ? interval * cfg.silentMultiplier : null;
  const durs = oks.map((r) => (r.stop && r.start ? r.stop - r.start : null)).filter(Number.isFinite);
  const latest = done[0];
  const latestDur = latest && latest.stop ? latest.stop - latest.start : null;
  const base = median(latest && latest.status === 'success' ? durs.slice(1) : durs);

  let status = 'OK', reason = 'healthy';
  if (streak >= cfg.failStreak) { status = 'FAILING'; reason = `${streak} consecutive errors`; }
  else if (limit && runs.length && (sinceOk == null || (sinceOk > limit && !(streak > 0 && sinceRun <= limit)))) {
    status = 'SILENT'; reason = sinceOk == null ? 'no successful run in recent history' : `no success for ${fmt(sinceOk)} (expected every ${fmt(interval)})`;
  } else if (latestDur && base && durs.length >= 5 && latestDur > base * cfg.slowMultiplier) {
    status = 'SLOW'; reason = `last run ${(latestDur / base).toFixed(1)}x slower than median`;
  }

  const prev = store.incidents[wf.id];
  let kind = 'none';
  if (status !== 'OK' && (!prev || prev.status !== status)) { kind = 'incident'; store.incidents[wf.id] = { status, since: now }; }
  else if (status === 'OK' && prev) { kind = 'recovered'; delete store.incidents[wf.id]; }
  if (status !== 'OK' && wf.active === false) reason += ' · workflow is deactivated';

  const emoji = { SILENT: '🔕', FAILING: '🔴', SLOW: '🐢' }[status] || '✅';
  const title = kind === 'recovered' ? 'RECOVERED' : status;
  const lastOkTxt = lastOk ? new Date(lastOk).toISOString().replace('T', ' ').slice(0, 16) + ' UTC' : 'never';
  const link = `${$env.N8N_BASE_URL}/workflow/${wf.id}`;
  const text = `${emoji} *${title}* · *${wf.name}*\nClient: ${cfg.clientLabel}\n> ${kind === 'recovered' ? `Back to healthy after ${fmt((now - prev.since) / MIN)}` : reason}\nLast success: ${lastOkTxt} · Fail streak: ${streak}\n<${link}|Open workflow in n8n>`;
  out.push({ json: { workflowId: wf.id, name: wf.name, status, reason, kind, shouldAlert: kind !== 'none', text } });
}
return out.length ? out : [{ json: { shouldAlert: false, kind: 'none', note: 'no workflows' } }];
